//! AC2/AC3: Key lifecycle, security journal and projection parity.
//!
//! The expected outcomes are generated by
//! `tests/generate_rust_store_fixture.py` from the REAL Python
//! `share.store.ShareStore` with deterministic uuid/timestamp/secret sources.

use std::path::PathBuf;

use serde_json::{json, Value};
use um_store::{OperationRow, ShareStore, StoreError};

const ALPHA_SECRET: &str = "um-share-alpha-0123456789abcdef";
const BETA_SECRET: &str = "um-share-beta-0123456789abcdef";
const ROTATED_SECRET: &str = "um-share-rotated-token-0123456789abcdefghijklmnopqrstuvwxyz";

fn fixture() -> Value {
    let path = PathBuf::from(env!("CARGO_MANIFEST_DIR"))
        .join("../../..")
        .join("tests/fixtures/rust_store_rev1.json");
    serde_json::from_str(&std::fs::read_to_string(path).unwrap()).unwrap()
}

fn test_key() -> Vec<u8> {
    (0..32).collect()
}

fn deterministic(store: &mut ShareStore) {
    let mut uuid_index = 0;
    let mut now_index = 0;
    store.set_sources(
        Box::new(move || {
            uuid_index += 1;
            format!("00000000-0000-0000-0000-{uuid_index:012x}")
        }),
        Box::new(move || {
            now_index += 1;
            format!("2026-11-15T00:00:{now_index:02}.{now_index:06}Z")
        }),
        Box::new(|| ROTATED_SECRET.to_string()),
    );
}

fn error_value(error: StoreError) -> Value {
    json!({"error": error.kind(), "message": error.message()})
}

fn capture<T>(result: Result<T, StoreError>, map: impl FnOnce(T) -> Value) -> Value {
    match result {
        Ok(value) => map(value),
        Err(error) => error_value(error),
    }
}

fn operation_summary(operation: &OperationRow) -> Value {
    json!({
        "kind": operation.kind,
        "idempotency_key": operation.idempotency_key,
        "status": operation.status,
        "payload": operation.payload,
    })
}

fn operation_value(operation: &OperationRow) -> Value {
    json!({
        "id": operation.id,
        "kind": operation.kind,
        "idempotency_key": operation.idempotency_key,
        "status": operation.status,
        "payload": operation.payload,
        "created_at": operation.created_at,
    })
}

fn snapshot(store: &mut ShareStore) -> Value {
    json!({
        "generation": store.generation().unwrap(),
        "security": {
            "records": store.security_records().unwrap(),
            "floor": store.security_floor().unwrap(),
            "state": store.security_state().unwrap(),
        },
        "operations": store
            .operations(None, None)
            .unwrap()
            .iter()
            .map(operation_summary)
            .collect::<Vec<_>>(),
        "projection": store.render_projection().unwrap(),
        "keys": store.list_keys(true).unwrap(),
    })
}

#[test]
fn the_key_lifecycle_matches_the_python_store() {
    let fixture = fixture();
    let directory = tempfile::tempdir().unwrap();
    let path = directory.path().join("lifecycle.db");
    let mut store = ShareStore::open_with_key(&path, test_key()).unwrap();
    deterministic(&mut store);
    let mut steps: Vec<Value> = Vec::new();

    let created = store
        .create_key(
            "alpha",
            Some(ALPHA_SECRET),
            Some("create-alpha"),
            Some(16),
        )
        .unwrap();
    let alpha_id = created["key_id"].as_str().unwrap().to_string();
    steps.push(json!({"step": "create-alpha", "result": created}));

    let beta = store
        .create_key("beta", Some(BETA_SECRET), None, None)
        .unwrap();
    let beta_id = beta["key_id"].as_str().unwrap().to_string();
    steps.push(json!({"step": "create-beta", "result": beta}));

    steps.push(json!({
        "step": "create-duplicate",
        "result": capture(
            store.create_key("alpha", Some(ALPHA_SECRET), None, None),
            |value| value,
        ),
    }));
    steps.push(json!({
        "step": "replay-create",
        "result": store
            .create_key("alpha", Some(ALPHA_SECRET), Some("create-alpha"), Some(16))
            .unwrap(),
    }));
    steps.push(json!({"step": "get-alpha", "result": store.get_key(&alpha_id).unwrap()}));
    steps.push(json!({
        "step": "rename-alpha",
        "result": store
            .rename_key(&alpha_id, "alpha-renamed", Some(1))
            .unwrap(),
    }));
    steps.push(json!({
        "step": "stale-rename",
        "result": capture(
            store.rename_key(&alpha_id, "alpha-stale", Some(1)),
            |value| value,
        ),
    }));
    steps.push(json!({
        "step": "lower-concurrency",
        "result": store
            .update_key(&alpha_id, None, None, Some(8), Some(2))
            .unwrap(),
    }));
    steps.push(json!({
        "step": "reject-enable",
        "result": capture(
            store.update_key(&alpha_id, None, Some(true), None, None),
            |value| value,
        ),
    }));
    steps.push(json!({
        "step": "rotate-beta",
        "result": store
            .rotate_key(&beta_id, Some("rotate-beta"), None)
            .unwrap(),
    }));
    steps.push(json!({
        "step": "replay-rotate",
        "result": store
            .rotate_key(&beta_id, Some("rotate-beta"), None)
            .unwrap(),
    }));
    steps.push(json!({
        "step": "rotate-other-target",
        "result": capture(
            store.rotate_key(&alpha_id, Some("rotate-beta"), None),
            |value| value,
        ),
    }));
    steps.push(json!({
        "step": "delete-beta",
        "result": store.delete_key(&beta_id, None).unwrap(),
    }));
    steps.push(json!({
        "step": "delete-again",
        "result": store.delete_key(&beta_id, None).unwrap(),
    }));
    steps.push(json!({
        "step": "reveal-deleted",
        "result": capture(store.reveal_key_secret(&beta_id, None), |value| value),
    }));
    steps.push(json!({
        "step": "verify-alpha",
        "result": store.verify_secret(&alpha_id, ALPHA_SECRET).unwrap(),
    }));
    steps.push(json!({
        "step": "verify-wrong",
        "result": store.verify_secret(&alpha_id, BETA_SECRET).unwrap(),
    }));
    steps.push(json!({
        "step": "security-records",
        "result": store.security_records().unwrap(),
    }));
    steps.push(json!({
        "step": "commit-applied",
        "result": store.commit_applied(3, Some("instance-a"), Some(2)).unwrap(),
    }));
    steps.push(json!({
        "step": "security-after-ack",
        "result": store.security_records().unwrap(),
    }));
    steps.push(json!({
        "step": "set-limit-lower",
        "result": store
            .set_share_max_concurrency(32, Some(64), Some("limits-1"))
            .unwrap(),
    }));
    steps.push(json!({
        "step": "replay-limit",
        "result": store
            .set_share_max_concurrency(32, Some(64), Some("limits-1"))
            .unwrap(),
    }));
    steps.push(json!({"step": "snapshot", "result": snapshot(&mut store)}));
    let generation = store.generation().unwrap()["config_generation"]
        .as_i64()
        .unwrap();
    steps.push(json!({
        "step": "pending-intent",
        "result": store
            .find_pending_publish_intent(generation)
            .unwrap()
            .as_ref()
            .map(operation_value),
    }));

    let expected = fixture["lifecycle"].as_array().unwrap().clone();
    assert_eq!(steps.len(), expected.len(), "step count differs from Python");
    for (actual, expected) in steps.iter().zip(expected.iter()) {
        assert_eq!(
            actual, expected,
            "step '{}' differs from Python",
            expected["step"].as_str().unwrap_or("?")
        );
    }
}

#[test]
fn the_plaintext_readback_is_narrow_and_fail_closed() {
    let directory = tempfile::tempdir().unwrap();
    let path = directory.path().join("reveal.db");
    let mut store = ShareStore::open_with_key(&path, test_key()).unwrap();
    let created = store
        .create_key("alpha", Some(ALPHA_SECRET), None, None)
        .unwrap();
    let key_id = created["key_id"].as_str().unwrap().to_string();
    let revealed = store.reveal_key_secret(&key_id, Some(1)).unwrap();
    assert_eq!(revealed["secret"].as_str().unwrap(), ALPHA_SECRET);
    assert_eq!(revealed["secret_version"].as_i64().unwrap(), 1);
    assert_eq!(
        store
            .reveal_key_secret(&key_id, Some(99))
            .unwrap_err()
            .kind(),
        "VersionMismatch"
    );

    let rotated = store.rotate_key(&key_id, None, Some(1)).unwrap();
    let rotated_secret = rotated["secret"].as_str().unwrap();
    assert_ne!(rotated_secret, ALPHA_SECRET);
    assert_eq!(
        store.reveal_key_secret(&key_id, None).unwrap()["secret"]
            .as_str()
            .unwrap(),
        rotated_secret
    );

    store
        .connection()
        .execute(
            "INSERT INTO keys(key_id,name,secret_hash,secret_version,masked_key,\
             enabled,created_at,updated_at,deleted_at,row_version) \
             VALUES('legacy-row','legacy','aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa',\
             1,'legacy-****',1,'2026-11-15T00:00:00.000000Z','2026-11-15T00:00:00.000000Z',NULL,1)",
            [],
        )
        .unwrap();
    assert_eq!(
        store
            .reveal_key_secret("legacy-row", None)
            .unwrap_err()
            .kind(),
        "SecretUnavailable"
    );

    store.delete_key(&key_id, None).unwrap();
    assert_eq!(
        store.reveal_key_secret(&key_id, None).unwrap_err().kind(),
        "Disabled"
    );
}
